insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('b50d3139-7662-431d-a0e5-4ddfab45ba0e', '56828b94-790b-4446-a1fe-a948a3d92b94', $$inleiding: twee kortingsacties$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context1.png$$,
   $$Een schoenenzaak geeft korting op de wintercollectie. Er zijn twee kortingsacties (I en II) die met behulp van posters in de winkel onder de aandacht worden gebracht. Zie figuur 1.$$, 'inline'),
  ('7a983b56-07ac-4019-b1c8-76a18a72b8ff', '56828b94-790b-4446-a1fe-a948a3d92b94', $$figuur 1: posters kortingsactie I en II$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context2.png$$,
   $$figuur 1
kortingsactie I: Winter SALE (alleen op de wintercollectie) bij aankoop van elk paar schoenen 20% korting
kortingsactie II: Winter SALE (alleen op de wintercollectie) bij aankoop van 2 paar schoenen 2e paar schoenen voor de halve prijs* *geldig voor het goedkoopste paar$$, 'inline'),
  ('3925060b-dd9c-4def-ae93-0f7033b94112', '56828b94-790b-4446-a1fe-a948a3d92b94', $$Famke en Milla kopen schoenen$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context3.png$$,
   $$Twee vriendinnen, Famke en Milla, gaan schoenen kopen.$$, 'inline'),
  ('94e1c436-5ccf-456f-a148-07659f44381c', '56828b94-790b-4446-a1fe-a948a3d92b94', $$aankoop Famke$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context4.png$$,
   $$Famke koopt twee paar schoenen: een paar van 100 euro en een paar van 80 euro. Ze wil gebruikmaken van kortingsactie II.$$, 'inline'),
  ('c83ad300-dc5c-4be2-aed9-bc40c78a9c7d', '56828b94-790b-4446-a1fe-a948a3d92b94', $$aankoop Milla$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context5.png$$,
   $$Milla koopt ook twee paar schoenen: een paar van 100 euro en een paar van 40 euro.$$, 'inline'),
  ('619df709-981d-4dc1-83e7-bd96fbf28add', '56828b94-790b-4446-a1fe-a948a3d92b94', $$figuur 2: inleiding$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context6.png$$,
   $$We bekijken het kopen van twee paar schoenen uit de wintercollectie met korting. In figuur 2 staat langs de verticale as de prijs van het duurste paar en langs de horizontale as de prijs van het goedkoopste paar schoenen.$$, 'inline'),
  ('d9c1befa-eec1-489d-a2f1-5087565906af', '56828b94-790b-4446-a1fe-a948a3d92b94', $$figuur 2: prijs duurste tegen goedkoopste paar$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context7.png$$,
   $$figuur 2
verticale as: duurste paar schoenen in euro (0 – 220); horizontale as: goedkoopste paar schoenen in euro (0 – 220)
twee lijnen door de oorsprong verdelen de figuur in gebied A, gebied B en gebied C$$, 'inline'),
  ('db29a2e8-d3d9-4ff6-a399-6a0cee55ae22', '56828b94-790b-4446-a1fe-a948a3d92b94', $$gebieden A, B en C$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context8.png$$,
   $$In de figuur zijn twee lijnen getekend waardoor er drie gebieden A, B en C zijn. Eén van deze drie gebieden geeft combinaties van prijzen van het duurste en goedkoopste paar schoenen weer, waarbij kortingsactie II voordeliger is dan kortingsactie I.$$, 'inline'),
  ('33f9c2eb-cae6-4ef0-88a3-f4624c8496a1', '56828b94-790b-4446-a1fe-a948a3d92b94', $$final wintersale$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context9.png$$,
   $$Ondanks de kortingsacties is de wintercollectie na enkele weken nog steeds niet helemaal verkocht. De schoenenzaak gaat daarom over tot een nieuwe kortingsactie waarin nog meer korting wordt gegeven: de ‘final wintersale’. Zie figuur 3. Deze final wintersale bestaat ook weer uit twee kortingsacties (I en II), waarover het in de rest van deze opgave gaat.$$, 'inline'),
  ('04349856-6ad1-4864-810c-c3c4c12c23f0', '56828b94-790b-4446-a1fe-a948a3d92b94', $$figuur 3: posters final wintersale$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context10.png$$,
   $$figuur 3
kortingsactie I: FINAL Winter SALE (alleen op de wintercollectie) bij aankoop van elk paar schoenen 30% korting
kortingsactie II: FINAL Winter SALE (alleen op de wintercollectie) bij aankoop van 2 paar schoenen 2e paar schoenen voor een kwart van de prijs* *geldig voor het goedkoopste paar$$, 'inline'),
  ('7ed027be-9724-4369-946d-af42fd877b77', '56828b94-790b-4446-a1fe-a948a3d92b94', $$kortingsactie II niet altijd voordeliger$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context11.png$$,
   $$De meeste klanten denken nu dat bij de aankoop van twee paar schoenen kortingsactie II altijd meer korting oplevert dan kortingsactie I. Dit is echter niet juist.$$, 'inline'),
  ('230c09c0-5a22-46f2-8d19-1a3806a11ac5', '56828b94-790b-4446-a1fe-a948a3d92b94', $$formules korting Kᵢ en Kᵢᵢ$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context12.png$$,
   $$Stel dat het goedkoopste paar G euro kost en het duurste paar f keer zo duur is. Dan kunnen we de (totale) korting (in euro) berekenen voor beide kortingsacties met de onderstaande formules:
Korting bij kortingsactie I: Kᵢ = 0,3 · G + 0,3 · f · G
Korting bij kortingsactie II: Kᵢᵢ = 0,75 · G
Als bijvoorbeeld het goedkoopste paar schoenen 30 euro kost en het duurste paar drie keer zo duur is, dan is de totale korting bij kortingsactie I gelijk aan 0,3 · 30 + 0,3 · 3 · 30 = 36 euro.$$, 'inline'),
  ('8360eb7c-64b1-4d8a-879b-a4b5bdd26088', '56828b94-790b-4446-a1fe-a948a3d92b94', $$goedkoopste paar 75 euro$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context13.png$$,
   $$Stel dat het goedkoopste paar 75 euro kost.$$, 'inline'),
  ('190a3b9e-f2af-4876-a80f-8b2be4dcaa6d', '56828b94-790b-4446-a1fe-a948a3d92b94', $$formule voor het te betalen bedrag B$$,
   $$wiskunde-a-havo-2025-ii-uitverkoop-context14.png$$,
   $$Met behulp van de formule voor Kᵢ kunnen we een formule opstellen voor het bedrag B (in euro) dat de klant uiteindelijk moet betalen bij kortingsactie I:
B = 0,7 · G + 0,7 · f · G$$, 'inline'),
  ('4578b249-ca9f-4dd7-92c3-8e46c15791be', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$inleiding: vlindertellingen$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context1.png$$,
   $$Voor de Vlinderstichting tellen vrijwilligers in heel Nederland vlinders vanaf maart tot en met september. Deze vlindertellingen vinden al meerdere jaren plaats. De vrijwilligers tellen dan alle vlinders die ze zien, één keer per week, op een vaste dag en op vaste routes van ongeveer een kilometer.$$, 'inline'),
  ('3211ed3e-9003-4e07-8990-ce15bc97594a', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$aantal vaste routes 1989 en 2014$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context2.png$$,
   $$In 1989 telden vrijwilligers vlinders op 69 vaste routes. Sindsdien steeg het aantal vaste routes waarop vrijwilligers vlinders telden vrijwel lineair tot 394 routes in 2014.$$, 'inline'),
  ('c7e091e6-c8df-4fde-8797-33e20446d3ce', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 1: inleiding$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context3.png$$,
   $$In figuur 1 zie je per jaar het gemiddeld aantal getelde vlinders per route weergegeven voor de periode 1990-2014. Zo zie je dat in 1990 gemiddeld bijna 600 vlinders per route geteld zijn. Het gemiddelde over de hele periode 1990-2014 is met de horizontale lijn aangegeven. In 1990 is het gemiddeld aantal getelde vlinders per route lager dan het gemiddelde over de periode 1990-2014.$$, 'inline'),
  ('6f3acfdb-de20-4778-81ce-f00a55445b31', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 1: gemiddeld aantal getelde vlinders per route$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context4.png$$,
   $$figuur 1 gemiddeld aantal getelde vlinders per route
staafdiagram: verticale as gemiddeld aantal getelde vlinders per route (0 – 1200); horizontale as jaar (1990 – 2014); horizontale lijn: gemiddelde over de hele periode$$, 'inline'),
  ('e869f44c-cdd0-489b-a7a0-07b4ab68686e', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 2: inleiding$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context5.png$$,
   $$Tijdens de vlindertelling zijn in een bepaald gebied drie vlindersoorten geteld. In figuur 2 zie je van deze drie vlindersoorten de getelde aantallen in 2020 (zwarte lijn) en de gemiddelde aantallen in de periode 1990-2019 (grijze lijn). De schaalverdeling op de assen is bij elk van de drie grafieken hetzelfde.$$, 'inline'),
  ('a173c4de-7673-4cf7-8a35-447683c59d22', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 2: drie vlindersoorten in 2020 en gemiddeld 1990-2019$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context6.png$$,
   $$figuur 2
drie grafieken: veldparelmoervlinder, bruin zandoogje, eikenpage; horizontale as apr – okt (voorjaar, zomer, herfst)
Legenda:
— aantal getelde vlinders per dag in 2020 (zwart)
— gemiddeld aantal getelde vlinders per dag in de periode 1990-2019 (grijs)$$, 'inline'),
  ('4158d929-7e52-4687-903d-64f889c5b7d4', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$stellingen I, II en III$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context7.png$$,
   $$Bij figuur 2 zijn de volgende stellingen geformuleerd:
I Deze vlindersoort wordt in 2020 tijdens een kortere periode waargenomen dan gemiddeld in de periode 1990-2019.
II Deze vlindersoort is de meest waargenomen vlinder in 2020.
III In het voorjaar van 2020 wordt deze vlindersoort vaker waargenomen dan gemiddeld in de periode 1990-2019.$$, 'inline'),
  ('4dda8eff-2909-4571-878e-434b648b42e9', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$elke stelling van toepassing$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context8.png$$,
   $$Elke stelling is van toepassing op minstens een van de drie vlindersoorten in figuur 2.$$, 'inline'),
  ('602212b8-cef3-4663-9114-25339af71012', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 3: argusvlinders met trendlijn (logaritmische schaal)$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context9.png$$,
   $$In figuur 3 zie je hoe het aantal getelde argusvlinders in een bepaald gebied zich in de loop van de tijd ontwikkeld heeft. De aantallen zijn op een logaritmische schaal weergegeven.
figuur 3 argusvlinders
verticale as (logaritmisch): aantal argusvlinders (100 – 100 000); horizontale as: jaar (1990 – 2014)
Legenda: aantal argusvlinders (doorgetrokken lijn), trendlijn (gestippeld)
De rechte lijn in figuur 3 is de trendlijn. Volgens deze trendlijn neemt het aantal argusvlinders af.$$, 'inline'),
  ('d0378a16-fb65-4e47-a2bb-4871d837abc5', 'e13c2264-3976-47c3-abd7-8f9678dab791', $$figuur 4: mate van bedreiging per soortgroep 2019$$,
   $$wiskunde-a-havo-2025-ii-vlindertellingen-context10.png$$,
   $$Bij de Vlinderstichting worden behalve de gegevens van vlinders ook de gegevens van andere insectensoorten verwerkt, zoals van libellen. In figuur 4 zie je hoe het met de verschillende soortgroepen gaat in 2019.
figuur 4 mate van bedreiging per soortgroep 2019
gestapelde staafdiagrammen (0% – 100%) voor steenvliegen, eendagsvliegen, vlinders, bijen, libellen, sprinkhanen en krekels
Legenda: zeer enstig bedreigd, enstig bedreigd, bedreigd, licht bedreigd, zeer licht bedreigd, niet bedreigd$$, 'inline'),
  ('1c733365-11fd-48fa-8768-3da62941f458', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$internationale armoedegrens$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context1.png$$,
   $$De Wereldbank stelt dat iemand in extreme armoede leeft wanneer hij of zij moet leven van minder dan 1,90 Amerikaanse dollar (US$) per dag¹⁾. Dit bedrag wordt de internationale armoedegrens genoemd.$$, 'inline'),
  ('b2c672b1-7ec1-4b94-887b-602c91315b58', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$tabel: inleiding$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context2.png$$,
   $$In de tabel staat, voor de periode 1990-2015, uitgaand van de internationale armoedegrens, hoeveel mensen wereldwijd in extreme armoede leefden en welk percentage van de wereldbevolking dat was.$$, 'inline'),
  ('cd318e28-d910-491c-aa97-ec6ae38c02bc', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$tabel: aantal mensen wereldwijd in extreme armoede$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context3.png$$,
   $$tabel aantal mensen wereldwijd in extreme armoede
jaar | 1990 | 1993 | 1996 | 1999 | 2002 | 2005 | 2008 | 2011 | 2013 | 2015
aantal (miljoenen) | 1895 | 1878 | 1703 | 1729 | 1610 | 1352 | 1223 | 963 | 804 | 736
percentage van de wereldbevolking | 35,9 | 33,9 | 29,4 | 28,6 | 25,7 | 20,8 | 18,1 | 13,7 | 11,2 | 10,0$$, 'inline'),
  ('2e43629a-667b-4b1c-9a16-8523e5923bd5', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$ambitie Wereldbank: onder 3,0 in 2030$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context4.png$$,
   $$In 2015 had de Wereldbank de ambitie om het percentage van de wereldbevolking dat in extreme armoede leeft, uiterlijk in het jaar 2030 onder de 3,0 te krijgen. De Wereldbank rapporteert dat in de periode 1990-2015 dit percentage bij benadering jaarlijks met 1 afnam. Neem aan dat deze constante daling zich na 2015 op dezelfde wijze voortzet.$$, 'inline'),
  ('3c8b1aec-7b92-4474-a748-9d93261bbe8a', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$formule wereldbevolking B = 5,28 · 1,013ᵗ$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context5.png$$,
   $$We nemen aan dat de wereldbevolking in de periode van 1990-2015 exponentieel groeide en we maken gebruik van de gegevens van 1990 en 2015. Hieruit volgt de volgende formule, die een goede benadering voor de omvang van de wereldbevolking geeft:
B = 5,28 · 1,013ᵗ
Hierin is B de wereldbevolking in miljarden en t het aantal jaren na 1990.$$, 'inline'),
  ('8e7a427b-4ba5-4818-bbe0-995114fbbfcb', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$noot 1$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context6.png$$,
   $$noot 1 uitgaande van basisjaar 2011$$, 'inline'),
  ('7e434002-b210-4ad9-91f2-ef68872f4ce7', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$nationale armoedegrens N en welvaartsscore W$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context7.png$$,
   $$De internationale armoedegrens is voor iedereen in de wereld gelijk, dus onafhankelijk van het land waarin iemand leeft. Onderzoekers bij de Wereldbank hebben voorgesteld om bij studies naar extreme armoede ook te kijken naar een nationale armoedegrens N (in US$ per persoon per dag²⁾). Deze grens verschilt per land en ligt hoger naarmate een land welvarender is. Hoe welvarend een land is, wordt uitgedrukt in de welvaartsscore W (in US$ per persoon per dag).
In de figuur is van diverse landen het verband weergegeven tussen de nationale armoedegrens N en de welvaartsscore W. Beide assen in de figuur hebben een logaritmische schaalverdeling. Er is een lijn getekend die past bij de losse punten in het rechterdeel van de figuur.$$, 'inline'),
  ('9b074a45-1901-4425-a667-c86fda723e23', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$figuur: nationale armoedegrens en welvaartsscore$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context8.png$$,
   $$figuur nationale armoedegrens en welvaartsscore
verticale as (logaritmisch): N (US$ p.p.p.d.), met 1; 1,9; 10
horizontale as (logaritmisch): W (US$ p.p.p.d.), met 1; 1,9; 10$$, 'inline'),
  ('e10340a3-9ace-4b19-8dfb-6e2ef6040e5f', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$welvaartsscore 8$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context9.png$$,
   $$Een land heeft een welvaartsscore van 8.$$, 'inline'),
  ('c0f1f900-52fc-4c17-a35c-113f485d1d17', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$noot 2$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context10.png$$,
   $$noot 2 uitgedrukt in US$ ten opzichte van 2011 per persoon per dag (US$ p.p.p.d)$$, 'inline'),
  ('ed29c442-f976-4f08-b87a-58b882a4587f', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$formule 1$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context11.png$$,
   $$In de figuur is te zien dat de nationale armoedegrens nooit onder de internationale armoedegrens van 1,9 komt. In de figuur is een lijn getekend door de punten met W ≥ 10. Bij deze lijn past de formule:
N = 0,88 · W⁰,⁸³ (formule 1)$$, 'inline'),
  ('213bfabd-5798-4878-9123-af997da9b244', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$formule 2 en betekenis N en W$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context12.png$$,
   $$De onderzoekers gebruikten echter in hun rapport een andere formule:
N = 1,00 + 0,5 · W (formule 2)
In beide formules is N de nationale armoedegrens van een land en W de welvaartsscore van dat land, beide in US$ per persoon per dag.
Beide formules zijn geldig voor W ≥ 10.$$, 'inline'),
  ('4b6e5392-8917-401d-ae19-86f00bdd1d95', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$formule 2 geeft grotere uitkomst$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context13.png$$,
   $$Formule 2 geeft steeds een grotere uitkomst voor N dan formule 1.
De onderzoekers konden formule 2 toch gebruiken, omdat de uitkomsten van de twee formules niet veel van elkaar verschillen voor bepaalde welvaartsscores W.$$, 'inline'),
  ('ebd257e4-7b70-4c54-bdf8-ea86565fc913', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$andere kijk op extreme armoede$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context14.png$$,
   $$Het gebruik van de nationale armoedegrens in plaats van de internationale armoedegrens leidt tot een andere kijk op de omvang van het probleem van extreme armoede in de wereld.$$, 'inline'),
  ('f43925d8-ed2f-42e9-b158-f0e314b4632d', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$formules Aᵢ en Aₙ$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context15.png$$,
   $$Voor het aantal mensen dat in extreme armoede leeft, gelden bij benadering de volgende formules:
Aᵢ = (35,9 − 1,04 · t) · 0,0528 · 1,013ᵗ
Aₙ = (44,2 − 0,51 · t) · 0,0528 · 1,013ᵗ$$, 'inline'),
  ('962d9d36-ddbd-427e-877d-90d28a7fcd72', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$betekenis Aᵢ, Aₙ en t$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context16.png$$,
   $$Hierin is Aᵢ het aantal mensen (in miljarden) dat in extreme armoede leeft bij gebruik van de internationale armoedegrens, Aₙ het aantal mensen (in miljarden) dat in extreme armoede leeft bij gebruik van de nationale armoedegrens en t het aantal jaren na 1990.$$, 'inline'),
  ('85b2fdd7-aebe-4de9-a287-e4eb31797b28', '40480e3a-4f81-4118-a3f0-0cb097ccd0bd', $$geen mensen meer in extreme armoede volgens Aᵢ$$,
   $$wiskunde-a-havo-2025-ii-extreme-armoede-context17.png$$,
   $$Er komt een moment waarop er geen mensen meer in extreme armoede leven, wanneer je uitgaat van de formule van Aᵢ.$$, 'inline'),
  ('19050ff7-39bd-4a28-9b6a-5666888d321d', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$inleiding: telefonisch onderzoek met 1003 deelnemers$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context1.png$$,
   $$In opdracht van De Nederlandsche Bank is in februari 2023 onderzocht hoe (volwassen) Nederlanders het uiterlijk van (euro)bankbiljetten waarderen. Het onderzoek is uitgevoerd door middel van telefonische interviews. Er zijn daarvoor 20 823 telefoonnummers willekeurig door een computer bedacht. Daarvan bleek 51% geen gehoor te geven, in gesprek te zijn of er was sprake van een niet bestaand nummer. De resterende telefoonnummers leverden 1003 deelnemers op die meegedaan hebben aan het telefonisch interview.$$, 'inline'),
  ('6990e839-b303-453f-8ee1-ea18cfc8e8fa', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$steekproef uit de populatie$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context2.png$$,
   $$De 1003 deelnemers vormen op deze manier een steekproef uit de populatie Nederlanders.$$, 'inline'),
  ('0e58cd74-a1a9-4f51-981c-e1abc2e054c3', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$kenmerken (statistische variabelen)$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context3.png$$,
   $$Bij de deelnemers aan het telefonisch interview werd gevraagd naar een aantal kenmerken (statistische variabelen) zoals
− het geslacht,
− de leeftijd (in jaren),
− het aantal leden van het huishouden,
− het wel of niet beroepsmatig omgaan met bankbiljetten,
− de provincie waarin men woont.$$, 'inline'),
  ('340b6c45-bab8-4183-bd29-f3f12726842c', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$figuur: inleiding$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context4.png$$,
   $$In het onderzoek is ook gevraagd naar de waardering van de bankbiljetten. Zie de figuur voor het resultaat.$$, 'inline'),
  ('168ddea8-c162-4e3f-a876-e9cea08e4e28', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$figuur: waardering van de bankbiljetten$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context5.png$$,
   $$figuur
staafdiagram (0% – 100%) met de percentages 11%, 35%, 44%, 3%, 2%, 5%
Legenda: erg mooi, tamelijk mooi, niet mooi, niet lelijk, tamelijk lelijk, erg lelijk, geen waardering gegeven$$, 'inline'),
  ('577fa588-990d-4fed-89ec-0fc0d78c3644', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$percentage erg mooi of tamelijk mooi$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context6.png$$,
   $$Je kunt met de gegevens in de figuur berekenen hoeveel procent van de deelnemers die wel hun waardering van de bankbiljetten hebben gegeven, de bankbiljetten ‘erg mooi’ of ‘tamelijk mooi’ vindt.$$, 'inline'),
  ('4ef9c02c-cb05-451d-83d2-8a8bb98996ed', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$onderzoeken representatief$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context7.png$$,
   $$Ook in andere jaren is er onderzoek gedaan naar de waardering van bankbiljetten. In de rest van deze opgave gaan we ervan uit dat alle onderzoeken naar de waardering van de bankbiljetten representatief zijn voor Nederlanders.$$, 'inline'),
  ('bc4c2a53-5381-4f97-9534-841e1edbab28', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$formule voor Pₘₒₒᵢ: inleiding$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context8.png$$,
   $$Om de waardering van de bankbiljetten te meten, gebruikt men de volgende formule om het percentage ‘mooi’ (Pₘₒₒᵢ) te berekenen:$$, 'inline'),
  ('8b2a300a-a48b-43e4-8a4b-0b18c73364d7', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$formule Pₘₒₒᵢ$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context9.png$$,
   $$Pₘₒₒᵢ = (aantal ‘erg mooi’ + aantal ‘tamelijk mooi’ + 0,5 × aantal ‘niet mooi, niet lelijk’) / (totaal aantal deelnemers − aantal ‘geen waardering gegeven’) · 100$$, 'inline'),
  ('89e2601b-09a6-4fd7-8e85-cae59b5563ba', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$betekenis aantal in de formule$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context10.png$$,
   $$In deze formule staat bijvoorbeeld aantal ‘erg mooi’ voor het aantal onderzoeksdeelnemers dat aangeeft de bankbiljetten ‘erg mooi’ te vinden.$$, 'inline'),
  ('7f40bdaa-8428-421d-862d-1cfbea9ff407', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$Pₘₒₒᵢ in 2002 is 65$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context11.png$$,
   $$In 2002 was Pₘₒₒᵢ gelijk aan 65. Met de gegevens in de figuur over het onderzoek onder de 1003 deelnemers in 2023 en de formule kunnen we nu Pₘₒₒᵢ in 2023 en in 2002 vergelijken.$$, 'inline'),
  ('e69fc840-760f-490b-85c5-f3a5406a1a1e', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$heroverweging deelnemers zonder waardering$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context12.png$$,
   $$Stel dat een aantal van de onderzoeksdeelnemers die geen waardering hebben gegeven voor de bankbiljetten, bij een heroverweging toch beslissen de bankbiljetten ‘tamelijk lelijk’ te vinden, en dat de overige deelnemers bij hun standpunt blijven. Dan zal de waardering van de bankbiljetten afnemen.$$, 'inline'),
  ('4c52ef88-90d4-4816-852a-c29cf794b45c', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$groepen A en B$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context13.png$$,
   $$De 1003 deelnemers aan het onderzoek in 2023 zijn op basis van het kenmerk ‘wel of niet beroepsmatig omgaan met bankbiljetten’ onderverdeeld in de groepen A en B. Zie de tabel.$$, 'inline'),
  ('c33bde39-a975-4438-8c82-3d037c8d9937', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$tabel: percentage deelnemers groep A en B$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context14.png$$,
   $$tabel percentage deelnemers groep A en B in 2023
groep A | beroepsmatig omgaan met bankbiljetten | 17,1%
groep B | niet beroepsmatig omgaan met bankbiljetten | 82,9%$$, 'inline'),
  ('414087ab-3e15-4a56-ba78-848782bef6b0', 'de27a83f-2b57-4217-88f8-06a3caaac4f1', $$verwachting minder contant geld: 50% en 61%$$,
   $$wiskunde-a-havo-2025-ii-eurobankbiljetten-context15.png$$,
   $$Er blijkt een verschil te bestaan tussen groep A en B: 50% van de deelnemers in groep A en 61% van de deelnemers in groep B verwacht dat er over vijf jaar minder met contant geld betaald zal worden.$$, 'inline'),
  ('0bdbffe5-0a88-405d-9f1b-44bf9f464eb9', 'f317a576-5f6d-495e-ac40-d6785bf7c033', $$inleiding: topinkomen$$,
   $$wiskunde-a-havo-2025-ii-topinkomens-context1.png$$,
   $$Er is sprake van een topinkomen als het inkomen van iemand in een jaar (gemeten op 31 december) 100 000 euro of meer is. Het aantal personen met zo’n topinkomen in Nederland is vanaf 2011 sterk toegenomen, zie de figuur.$$, 'inline'),
  ('7dfbdd8c-e939-447f-a448-58046583cc7d', 'f317a576-5f6d-495e-ac40-d6785bf7c033', $$figuur: aantal personen met een topinkomen 2011-2017$$,
   $$wiskunde-a-havo-2025-ii-topinkomens-context2.png$$,
   $$figuur aantal personen in Nederland met een topinkomen
verticale as: aantal personen; horizontale as: jaar (2011 – 2017); gebieden: man, vrouw$$, 'inline'),
  ('4a1ba28e-6cfb-47d3-b945-c39315586f5c', 'f317a576-5f6d-495e-ac40-d6785bf7c033', $$aantallen 2011 en 2017; zeven en vijf keer zoveel mannen$$,
   $$wiskunde-a-havo-2025-ii-topinkomens-context3.png$$,
   $$In 2017 waren er 13,4 miljoen personen in Nederland met een inkomen. Daarvan hadden er 360 000 een topinkomen. Dat waren 120 000 personen meer dan in 2011. Het aantal vrouwen met een topinkomen groeide in de periode 2011-2017 relatief sterker dan het aantal mannen met een topinkomen. In 2011 waren er zeven keer zoveel mannen als vrouwen met een topinkomen. In 2017 was dat nog maar vijf keer zoveel.$$, 'inline'),
  ('a94d05ec-6eb9-4a18-9ca2-38f307d6d613', 'f317a576-5f6d-495e-ac40-d6785bf7c033', $$vast groeipercentage per jaar$$,
   $$wiskunde-a-havo-2025-ii-topinkomens-context4.png$$,
   $$Neem aan dat zowel het aantal mannen met een topinkomen als het aantal vrouwen met een topinkomen groeide met een vast percentage per jaar in de periode 2011-2017 en dat deze groei zich voortzet in de jaren na 2017.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('95d13bac-23c4-4551-ac3e-80def55746d1', '56828b94-790b-4446-a1fe-a948a3d92b94', 1,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["procentuele korting", "kortingspercentage", "procenten berekenen", "halve prijs", "afronden op hele procenten"]'::jsonb,
